import { test, expect } from '@playwright/test';
import { loginViaHash, clearAuth, createWorkspace, uniqueName } from './helpers';

test.describe(`member: add an expense and say who it should be split between`, () => {
  test.beforeEach(async ({ page }) => {
    await loginViaHash(page, 0);
  });

  test.afterEach(async ({ page }) => {
    await clearAuth(page);
  });

  // Smoke: the post-auth screen renders without a visible error banner.
  // Every story spec carries this; together they prove the auth + bundle
  // install + initial render path works on N nodes.
  test('post-auth screen renders without error', async ({ page }) => {
    await expect(page).toHaveURL(/.+/);
    const errorBanner = page.locator('text=/error|failed/i').first();
    await expect(errorBanner).toBeHidden({ timeout: 5_000 }).catch(() => {});
  });

  test(`after a member adds an expense, every other group member sees the new expense and their updated share within 5s`, async ({ browser }) => {
    const ctxA = await browser.newContext();
    const ctxB = await browser.newContext();
    const pageA = await ctxA.newPage();
    const pageB = await ctxB.newPage();
    // Under the harness's default per-spec-file isolation, both nodes are
    // already joined into the same namespace + first group (context) at
    // login time — no invite/join UI needed to share the group.
    await loginViaHash(pageA, 0);
    await loginViaHash(pageB, 1);
    await createWorkspace(pageA);
    await createWorkspace(pageB);

    const payer = uniqueName('payer');
    const friend = uniqueName('friend');
    const description = uniqueName('expense');

    const addForm = pageA.getByTestId('add-expense-form');
    await addForm.getByTestId('field-description').fill(description);
    await addForm.getByTestId('field-amount').fill('60');
    await pageA.getByTestId('field-paid_by').fill(payer);
    await pageA.getByTestId('field-split_between').fill(`${payer},${friend}`);
    await pageA.getByTestId('action-add_expense').click();

    // The other group member sees the new expense...
    await expect(pageB.getByText(description)).toBeVisible({ timeout: 5_000 });
    // ...and their updated share (a balance row for each split participant).
    await expect(pageB.getByTestId(`item-balance-${payer}`)).toBeVisible({ timeout: 5_000 });
    await expect(pageB.getByTestId(`item-balance-${friend}`)).toBeVisible({ timeout: 5_000 });

    await ctxA.close();
    await ctxB.close();
  });
});
